def generate(rng):
    H, W = 14, 13
    g = [[0]*W for _ in range(H)]
    # Several independent horizontal 5-cell bars, each with a 2 marker above
    bars = []
    for r in [2, 6, 9, 13]:
        c = rng.choice([1,2,4,5,7])
        if c+4 < W:
            bars.append((r,c))
